// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy, Bank} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        GoodBank g = new GoodBank();
        try g.callDrop(c) {
            assertTrue(c.tokenBalance(address(g)) == 20, "airDrop from a valid Bank must credit 20 tokens");
        } catch {
            assertTrue(false, "airDrop from a valid Bank must not revert");
        }
    }
}

contract GoodBank is Bank {
    bool public called;
    function callDrop(ModifierEntrancy c) external {
        c.airDrop();
        called = true;
    }
}
